import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Standard 3D convolution (as defined by nn.Conv3d):
//   input : (N, C_in, D_in, H_in, W_in)  [contiguous]
//   weight: (C_out, C_in/groups, kD, kH, kW) [contiguous]
//   bias  : (C_out) or nullptr
//   output: (N, C_out, D_out, H_out, W_out) [contiguous]
//
// One thread per output element. The kernel dimension with extent 1 (kW here)
// and the small channel count make a direct accumulation kernel appropriate;
// overlapping input reads of neighboring threads are served from L1/L2 cache.

__global__ void conv3d_direct_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    long long total,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int pD, int pH, int pW,
    int dD, int dH, int dW,
    int groups,
    int has_bias)
{
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;

    // Decompose linear output index (W fastest for coalescing).
    int wo = (int)(idx % W_out);
    long long t = idx / W_out;
    int ho = (int)(t % H_out); t /= H_out;
    int do_ = (int)(t % D_out); t /= D_out;
    int co = (int)(t % C_out);
    int n  = (int)(t / C_out);

    int oc_per_g = C_out / groups;
    int ic_per_g = C_in / groups;
    int g = co / oc_per_g;
    int ci_start = g * ic_per_g;

    const float* wptr = w + (long long)co * ic_per_g * kD * kH * kW;

    float acc = has_bias ? b[co] : 0.0f;

    for (int ci = 0; ci < ic_per_g; ++ci) {
        int c = ci_start + ci;
        const float* xbase = x + (((long long)n * C_in + c) * D_in) * H_in * W_in;
        const float* wc = wptr + (long long)ci * kD * kH * kW;
        for (int kd = 0; kd < kD; ++kd) {
            int di = do_ * sD + kd * dD - pD;
            if (di < 0 || di >= D_in) continue;
            for (int kh = 0; kh < kH; ++kh) {
                int hi = ho * sH + kh * dH - pH;
                if (hi < 0 || hi >= H_in) continue;
                long long row = ((long long)di * H_in + hi) * W_in;
                const float* wk = wc + (kd * kH + kh) * kW;
                #pragma unroll
                for (int kw = 0; kw < kW; ++kw) {
                    int wi = wo * sW + kw * dW - pW;
                    if (wi < 0 || wi >= W_in) continue;
                    acc += xbase[row + wi] * wk[kw];
                }
            }
        }
    }

    y[idx] = acc;
}

torch::Tensor conv3d_forward(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor b,
    int64_t stride, int64_t padding, int64_t dilation, int64_t groups)
{
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "inputs must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
                "only float32 supported");
    TORCH_CHECK(x.dim() == 5 && w.dim() == 5, "bad ranks");

    auto xc = x.contiguous();
    auto wc = w.contiguous();

    int N = xc.size(0), C_in = xc.size(1), D_in = xc.size(2), H_in = xc.size(3), W_in = xc.size(4);
    int C_out = wc.size(0), kD = wc.size(2), kH = wc.size(3), kW = wc.size(4);

    int s = (int)stride, p = (int)padding, d = (int)dilation;
    int D_out = (D_in + 2 * p - d * (kD - 1) - 1) / s + 1;
    int H_out = (H_in + 2 * p - d * (kH - 1) - 1) / s + 1;
    int W_out = (W_in + 2 * p - d * (kW - 1) - 1) / s + 1;

    auto y = torch::empty({N, C_out, D_out, H_out, W_out}, xc.options());

    long long total = (long long)N * C_out * D_out * H_out * W_out;
    int threads = 256;
    long long blocks = (total + threads - 1) / threads;

    const float* bptr = (b.defined() && b.numel() > 0) ? b.contiguous().data_ptr<float>() : nullptr;
    int has_bias = bptr != nullptr ? 1 : 0;

    conv3d_direct_kernel<<<(unsigned int)blocks, threads>>>(
        xc.data_ptr<float>(), wc.data_ptr<float>(), bptr, y.data_ptr<float>(),
        total,
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        kD, kH, kW,
        s, s, s,
        p, p, p,
        d, d, d,
        (int)groups, has_bias);

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
"""

_cpp_src = r"""
torch::Tensor conv3d_forward(
    torch::Tensor x, torch::Tensor w, torch::Tensor b,
    int64_t stride, int64_t padding, int64_t dilation, int64_t groups);
"""

_ext = load_inline(
    name="conv3d_direct_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv3d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    3D convolution backed by a single custom CUDA kernel. Keeps an nn.Conv3d
    submodule purely as the parameter holder so state_dict layout matches the
    reference architecture exactly.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv3d = nn.Conv3d(in_channels, out_channels,
                                (kernel_size, kernel_size, 1),
                                stride=stride, padding=padding,
                                dilation=dilation, groups=groups, bias=bias)
        self._stride = self.conv3d.stride[0]
        self._padding = self.conv3d.padding[0]
        self._dilation = self.conv3d.dilation[0]
        self._groups = self.conv3d.groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # pybind11 cannot convert None to torch::Tensor; pass an empty tensor
        # instead. The C++ wrapper treats b.numel() == 0 as "no bias"
        # (bptr = nullptr, has_bias = 0), matching nn.Conv3d(bias=False).
        bias = self.conv3d.bias
        if bias is None:
            bias = x.new_empty(0)
        return _ext.conv3d_forward(
            x, self.conv3d.weight, bias,
            self._stride, self._padding, self._dilation, self._groups)

